<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['member']);verify_csrf();$uid=(int)current_user()['id'];$bid=(int)($_POST['book_id']??0);try{$conn->begin_transaction();$s=$conn->prepare('SELECT id,available_copies,is_archived FROM books WHERE id=? FOR UPDATE');$s->bind_param('i',$bid);$s->execute();$b=$s->get_result()->fetch_assoc();if(!$b||$b['is_archived']||$b['available_copies']<1)throw new Exception('No copies available.');$s=$conn->prepare("SELECT id FROM borrowings WHERE user_id=? AND book_id=? AND status IN('pending','approved','borrowed')");$s->bind_param('ii',$uid,$bid);$s->execute();if($s->get_result()->num_rows)throw new Exception('You already have an active request or loan for this book.');$s=$conn->prepare("SELECT id FROM reservations WHERE book_id=? AND status IN('pending','approved','ready') LIMIT 1");$s->bind_param('i',$bid);$s->execute();if($s->get_result()->num_rows)throw new Exception('This book has an active reservation queue. Please reserve it instead of submitting a direct borrowing request.');$s=$conn->prepare("INSERT INTO borrowings(user_id,book_id,status) VALUES(?,?,'pending')");$s->bind_param('ii',$uid,$bid);$s->execute();$conn->commit();log_activity($conn,$uid,'borrow_requested','Book ID '.$bid);flash('success','Request submitted. Wait for librarian approval.');}catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());}redirect('books.php');?>